function placeholder(){const label=nav.find(x=>x[0]===state.route)?.[2]||'Page';return shell(`<div class="page"><div class="page-head"><div><h1>${label}</h1><p>Reserved in UX/UI v0.1. This prototype focuses on the approved first vertical slice.</p></div></div><div class="card empty">${label} will use the same authoritative state + shared detail-shell model.</div></div>`,label)}

function render(){let html=state.route==='dashboard'?dashboard():state.route==='project'||state.route==='projects'?project():state.route==='task'||state.route==='tasks'?task():state.route==='agent'||state.route==='agents'?agent():placeholder();document.querySelector('#app').innerHTML=html;document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',()=>{const r=el.dataset.route;if(!r)return;state.route=r;history.replaceState({},'',`#${r}`);render()}));}
state.route=location.hash.replace('#','')||'dashboard';render();
